update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance pneumatique","mecanisme":"Nous mesurons le débit produit face au débit utile, puis nous localisons chaque fuite à l''ultrason. Nous les classons par débit perdu, et nous réparons ce qui compte en premier.","cta":"Demander une intervention","telephone":"04 78 33 72 05","phraseDelai":"Rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30. L''astreinte 24/24 et 7/7 prend le relais la nuit et le week-end."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, après entretien technique ET comportemental"},{"valeur":"4","libelle":"agences, plus des hubs techniques, pour partir du bassin le plus proche"},{"valeur":"24/24 et 7/7","libelle":"astreinte, pour les sites couverts"}]},{"type":"probleme","punchline":"Votre compresseur tourne le dimanche alors que l''atelier est vide. Ce n''est pas un problème de compresseur, c''est un réseau percé.","puces":[{"accroche":"L''air comprimé passe pour gratuit parce qu''il est invisible.","texte":"C''est l''énergie la plus chère de l''usine, et la seule que personne ne mesure."},{"accroche":"La fuite siffle, personne ne l''entend.","texte":"Dans le bruit de l''atelier, l''oreille humaine décroche. La facture d''électricité, elle, monte tous les jours."},{"accroche":"L''eau détruit le réseau en silence.","texte":"Purge bouchée, sécheur en défaut, et les distributeurs meurent les uns après les autres."},{"accroche":"La chute de pression en pointe arrête la ligne.","texte":"Plusieurs équipements démarrent ensemble, le réseau s''effondre, la production part en défaut sans cause apparente."}]},{"type":"offre","lignes":[{"prestation":{"accroche":"La chasse aux fuites","texte":"test de mise en charge, détection à l''ultrason, localisation et repérage, hiérarchisation par débit perdu, réparation, mesure finale."},"benefice":"Le gain est chiffré avant et après, pas promis. Il se lit sur la facture d''électricité."},{"prestation":{"accroche":"Une production d''air maîtrisée","texte":"compresseur, sécheur, cuve tampon, contrôle du débit et de la température de refoulement."},"benefice":"La machine reçoit la pression qu''elle attend, pas celle qui reste."},{"prestation":{"accroche":"Un traitement de l''air propre","texte":"filtres à particules, séparateurs d''eau, coalesceurs, purges automatiques."},"benefice":"Les particules et l''humidité cessent de tuer les composants en aval."},{"prestation":{"accroche":"Des actionneurs fiables","texte":"vérins simple et double effet, moteurs pneumatiques, pinces, ventouses. Dépose, révision, réglage."},"benefice":"La cadence remonte avant que quoi que ce soit ne casse."},{"prestation":{"accroche":"Une commande précise","texte":"distributeurs, électrovannes, régulateurs, limiteurs de débit, blocs de sécurité."},"benefice":"Le cycle cesse de se bloquer à mi-course."},{"prestation":{"texte":"**La baisse du réglage réseau et la suppression des usages inutiles.**"},"benefice":"Une pression excessive use tout le matériel et gonfle la facture pour rien."},{"prestation":{"accroche":"La panne mixte traitée en une visite","texte":"pneumatique, électricité, automatisme, mécanique sur la même équipe."},"benefice":"Un moteur pneumatique se diagnostique avec sa commande électrique, pas sans elle."}],"prose":[{"texte":"Vos arrêts se répètent toute l''année ? Le [contrat de maintenance Zéro arrêt](/offres/zero-arret/) intègre les contrôles périodiques du réseau. Une ligne bloquée maintenant se traite par le [dépannage industriel](/offres/depannage-industriel/)."}]},{"type":"deroule","etapes":[{"titre":"Vous décrivez la situation","texte":"équipement, symptôme, réglage réseau en place, contexte d''apparition. Quatre champs, ou un appel au 04 78 33 72 05."},{"titre":"Un technicien vous rappelle dans l''heure","texte":"le circuit est qualifié à distance, le bon profil et la bonne date sont arrêtés au téléphone."},{"titre":"Le test de mise en charge donne un premier chiffrage","texte":"réseau isolé, atelier à l''arrêt, mesure du temps de remontée. Une heure suffit à savoir où vous en êtes."},{"titre":"L''intervention se fait énergie pneumatique consignée.","texte":"Un actionneur encore sous charge reste dangereux, même machine éteinte."},{"titre":"Les fuites sont classées puis réparées","texte":"raccords, flexibles, purges, joints. Une fois la fuite localisée, la réparation est le plus souvent rapide."},{"titre":"Vous recevez un document de synthèse","texte":"points contrôlés, pièces remplacées, anomalies restantes, priorités pour la prochaine visite. De quoi justifier un budget d''une année sur l''autre."}]},{"type":"garanties","puces":[{"accroche":"Le rappel dans l''heure, du lundi au vendredi de 8h00 à 18h30.","texte":"L''astreinte 24/24 et 7/7 couvre la nuit et le week-end sur les sites concernés."},{"accroche":"Un gain mesuré, pas affirmé.","texte":"Mesure initiale, mesure finale, comparaison écrite. Vous savez ce qui fuyait, ce que cela coûtait et ce qui a été traité."},{"accroche":"Un technicien évalué en entretien technique et comportemental","texte":", 10 % des candidats retenus. Lecture de schéma pneumatique, méthode de recherche, choix du bon composant, réglage."}]},{"type":"cta","question":"Besoin de savoir combien votre réseau d''air comprimé perd chaque nuit ?","bouton":"Demander une intervention","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Renfort de maintenance pendant l''arrêt estival, équipements critiques","texte":"un technicien intégré à l''équipe, mécanique, électrotechnique et pneumatique couvertes par un seul profil, été 2025","lienLibelle":"Étude de cas OGF : arrêt estival","lienHref":"/preuves/ogf-arret-estival/"},{"titre":"Maintien opérationnel de convoyeurs, trieurs et packaging automatisés, logistique et transport","texte":"deux techniciens en poste, pneumatique comprise dans les domaines couverts en propre","lienLibelle":"Étude de cas GLS : maintenance curative","lienHref":"/preuves/gls-maintenance-curative/"},{"titre":"Contrat de maintenance préventive annuelle, logistique","texte":"six techniciens polyvalents en permanence sur les sites de Lyon, depuis septembre 2023","lienLibelle":"Étude de cas VEEPEE : sites de Lyon","lienHref":"/preuves/veepee-sites-lyon/"},{"titre":"Maintenance sous contrat d''un parc déployé partout en France, réalité virtuelle","texte":"périmètre technique complet, pneumatique comprise, depuis février 2024","lienLibelle":"Étude de cas TIMESCOPE : casques de réalité virtuelle","lienHref":"/preuves/timescope/"},{"titre":"Maintenance préventive et curative d''une fonderie","texte":"site tenu 7 jours sur 7 depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"}]},{"type":"objections","questions":[{"question":"Combien coûte une campagne de détection de fuites ?","reponse":"Le chiffrage dépend de l''étendue du réseau et du nombre de postes. Tout est établi sur devis. Comparez toujours ce montant au coût annuel de l''air perdu : le test initial vous donne ce chiffre avant de décider."},{"question":"Nous avons déjà un contrat d''entretien compresseur. Vous faites doublon ?","reponse":"Non. Un contrat compresseur couvre la machine qui produit l''air. Notre périmètre va du compresseur jusqu''au dernier actionneur, traitement, distribution et commande compris. C''est là que se cache la majorité des pertes."},{"question":"Qui répond de la sécurité pendant l''intervention ?","reponse":"Nos techniciens, dans votre cadre. Consignation des énergies, purge du circuit, plan de prévention signé, travail en hauteur et espaces confinés autorisés avant le déplacement. Vos procédures qualité et vos clauses de confidentialité sont respectées."},{"question":"Qui intervient sur nos circuits ?","reponse":"Des techniciens salariés de Migen, évalués en entretien technique et comportemental par un homme de terrain. 10 % des candidats sont retenus, et l''évaluation se poursuit sur le terrain."},{"question":"Faites-vous le montage de pneus sur véhicule ?","reponse":"Non. Le montage, l''équilibrage et le recreusage relèvent d''un atelier automobile et d''un autre métier. Notre activité porte sur l''air comprimé d''une usine et sur tout ce qu''il actionne."},{"question":"Couvrez-vous notre région, et les petites structures ?","reponse":"Oui aux deux. 4 agences, Lyon (siège), Montréal, Dubaï et Madrid, et des hubs de techniciens dans les grandes villes de France partout en France. Un réseau d''atelier se contrôle aussi utilement qu''un réseau d''usine."}]},{"type":"ctaFinal","question":"Besoin que votre compresseur arrête de tourner pour rien ?","bouton":"Demander une intervention"}]}'::jsonb where path = '/expertises/pneumatique/';
